export type ParsedMakerQuoteInstruction<
  TProgram extends string = typeof AGARI_MAKER_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    maker: TAccountMetas[0];
    vault: TAccountMetas[1];
    bookRecord: TAccountMetas[2];
    custody: TAccountMetas[3];
    seat: TAccountMetas[4];
    eventsProgram: TAccountMetas[5];
    eventsConfig: TAccountMetas[6];
    series: TAccountMetas[7];
    market: TAccountMetas[8];
    venueBook: TAccountMetas[9];
    ledger: TAccountMetas[10];
    mvault: TAccountMetas[11];
    collateralMint: TAccountMetas[12];
    tokenProgram: TAccountMetas[13];
    eventsEventAuthority: TAccountMetas[14];
    systemProgram: TAccountMetas[15];
  };
  data: MakerQuoteInstructionData;
};

export function parseMakerQuoteInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedMakerQuoteInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 16) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 16,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      maker: getNextAccount(),
      vault: getNextAccount(),
      bookRecord: getNextAccount(),
      custody: getNextAccount(),
      seat: getNextAccount(),
      eventsProgram: getNextAccount(),
      eventsConfig: getNextAccount(),
      series: getNextAccount(),
      market: getNextAccount(),
      venueBook: getNextAccount(),
      ledger: getNextAccount(),
      mvault: getNextAccount(),
      collateralMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      eventsEventAuthority: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getMakerQuoteInstructionDataDecoder().decode(instruction.data),
  };
}
